<?php
declare(strict_types=1);
use DataForm5\Packages\Core\PackageIntegrity;use DataForm5\Packages\Core\PackageManager;
$root=dirname(__DIR__);$tmp=$root.'/storage/framework/package-test';$installed=$root.'/storage/packages/installed';$registry=$root.'/storage/packages/installed.json';
$delete=function(string $p)use(&$delete):void{if(!file_exists($p))return;if(is_file($p)){unlink($p);return;}foreach(array_diff(scandir($p),['.','..']) as $x)$delete($p.'/'.$x);rmdir($p);};$delete($tmp);$delete($installed);@unlink($registry);mkdir($tmp.'/v1/payload',0775,true);file_put_contents($tmp.'/v1/payload/example.txt','v1');
$kernel=require $root.'/bootstrap/app.php';$pm=$kernel->container()->get(PackageManager::class);$integrity=$kernel->container()->get(PackageIntegrity::class);$checks=$integrity->calculate($tmp.'/v1/payload');file_put_contents($tmp.'/v1/package.json',json_encode(['name'=>'example-package','version'=>'1.0.0','type'=>'module','checksums'=>$checks],JSON_PRETTY_PRINT));$pm->install($tmp.'/v1');if(file_get_contents($installed.'/example-package/example.txt')!=='v1')throw new RuntimeException('Installation fehlgeschlagen.');
mkdir($tmp.'/v2/payload',0775,true);file_put_contents($tmp.'/v2/payload/example.txt','v2');$checks=$integrity->calculate($tmp.'/v2/payload');file_put_contents($tmp.'/v2/package.json',json_encode(['name'=>'example-package','version'=>'1.1.0','type'=>'module','checksums'=>$checks],JSON_PRETTY_PRINT));$pm->update($tmp.'/v2');if(($pm->installed()['example-package']['version']??'')!=='1.1.0')throw new RuntimeException('Update fehlgeschlagen.');$pm->uninstall('example-package');if(is_dir($installed.'/example-package'))throw new RuntimeException('Deinstallation fehlgeschlagen.');$delete($tmp);$delete($installed);@unlink($registry);echo "PASS: Package Manager\n";
